const $=(s,p=document)=>p.querySelector(s);const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const toast=(message)=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2200)};
$('#measureToggle').addEventListener('click',e=>{const panel=$('#measurements');panel.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',panel.classList.contains('open'));e.currentTarget.textContent=panel.classList.contains('open')?'− Hide measurements':'＋ Add measurements for a more precise fit'});
$('#petPhoto').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const p=$('#uploadPreview');p.style.backgroundImage=`linear-gradient(rgba(20,30,30,.06),rgba(20,30,30,.06)),url(${reader.result})`;p.classList.add('has-image');toast('Photo added — looking good')};reader.readAsDataURL(file)});
const syncName=()=>{const name=$('#petName').value.trim()||'Your pet';$$('.name-copy').forEach(x=>x.textContent=name.toUpperCase());$('#portraitName').textContent=name.toUpperCase();$$('.bandana').forEach(x=>x.textContent=name[0].toUpperCase())};$('#petName').addEventListener('input',syncName);
$('#createTwin').addEventListener('click',()=>{syncName();$('#petModel').animate([{transform:'translateX(-50%) scale(.85)',opacity:.4},{transform:'translateX(-50%) scale(1.12)',opacity:1},{transform:'translateX(-50%) scale(1.08)',opacity:1}],{duration:850,easing:'cubic-bezier(.2,.8,.2,1)'});toast('Pet twin ready — 92% size confidence')});
$('#rotatePet').addEventListener('click',()=>{$('#petModel').classList.toggle('flipped')});
$('#adjustFit').addEventListener('click',()=>{$('#measurements').classList.add('open');$('#measureToggle').setAttribute('aria-expanded','true');$('#studio').scrollIntoView({behavior:'smooth'});toast('Measurements opened')});
$$('.style').forEach(btn=>btn.addEventListener('click',()=>{$$('.style').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const canvas=$('#portraitCanvas');canvas.className='portrait-canvas '+(btn.dataset.style==='storybook'?'':btn.dataset.style)}));
$$('.palette button[data-color]').forEach(btn=>btn.addEventListener('click',()=>{document.documentElement.style.setProperty('--clay',btn.dataset.color);toast('Color story updated')}));
$('#generatePattern').addEventListener('click',e=>{e.currentTarget.disabled=true;e.currentTarget.innerHTML='Creating your pattern… <span>✦</span>';$('#portraitCanvas').animate([{filter:'saturate(.3)',transform:'scale(.98)'},{filter:'saturate(1.2)',transform:'scale(1.01)'},{filter:'saturate(1)',transform:'scale(1)'}],{duration:1400});setTimeout(()=>{e.currentTarget.disabled=false;e.currentTarget.innerHTML='Pattern ready <span>✓</span>';toast('Pattern concept ready to apply')},1400)});
$$('.filters button').forEach(btn=>btn.addEventListener('click',()=>{$$('.filters button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$$('.product').forEach(p=>p.classList.toggle('hidden',btn.dataset.filter!=='all'&&p.dataset.category!==btn.dataset.filter))}));
let bag=0;$$('.quick-add').forEach(btn=>btn.addEventListener('click',()=>{bag++;$('#bagCount').textContent=bag;btn.textContent='✓';toast(`${btn.dataset.product} added to your room`)}));
$$('.home-tabs button').forEach(btn=>btn.addEventListener('click',()=>{$$('.home-tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('#roomScene').className='room '+btn.dataset.room;$('.room-label b').textContent={sleep:'Golden hour garden',walk:'Ready for the park',dine:'Sunday supper'}[btn.dataset.room]}));
$('#saveRoom').addEventListener('click',e=>{e.currentTarget.innerHTML='Room saved <span>♥</span>';toast('Saved to your pet home')});
$('#bagButton').addEventListener('click',()=>toast(bag?`${bag} custom piece${bag>1?'s':''} saved — checkout is a future step`:'Your bag is waiting for something special'));
